/**
 * Review reproducers for LEO learned-feedback robustness (keys, confidence model, evidence ranking, rollout profile).
 * Every assertion states the robust expectation; a failure demonstrates the finding.
 */
class LeoLearningReviewReproTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	// ---------------------------------------------------------------- LeoOperatorKey collisions (candidate 6)

	@Test
	void sevenFactorConnectedChainAndCartesianTriangleTimesChainMustNotShareAKey() {
		// connected 7-edge chain a-b-c-d-e-f-g-h
		TupleExpr chain = leftDeep(p("a", "b"), p("b", "c"), p("c", "d"), p("d", "e"), p("e", "f"), p("f", "g"),
				p("g", "h"));
		// triangle a-b-c-a that is DISCONNECTED from chain d-e-f-g-h: a Cartesian product
		TupleExpr crossProduct = leftDeep(p("a", "b"), p("b", "c"), p("c", "a"), p("d", "e"), p("e", "f"),
				p("f", "g"), p("g", "h"));
		Join chainRoot = (Join) chain;
		Join crossRoot = (Join) crossProduct;
		// LMDB's OperatorKey adds only top-level left/right/shared binding names; show they are identical too.
		assertEquals(chainRoot.getLeftArg().getBindingNames(), crossRoot.getLeftArg().getBindingNames());
		assertEquals(chainRoot.getRightArg().getBindingNames(), crossRoot.getRightArg().getBindingNames());

		LeoOperatorKey chainKey = LeoOperatorKey.from(chain, "", LeoOperatorKey.ConstantMode.EXACT);
		LeoOperatorKey crossKey = LeoOperatorKey.from(crossProduct, "", LeoOperatorKey.ConstantMode.EXACT);
		assertNotEquals(chainKey, crossKey,
				"a connected chain and a Cartesian product must not share learned feedback; fingerprint="
						+ chainKey.structuralFingerprint());
	}

	@Test
	void filterConditionVariablesMustStayLinkedToTheFilteredJoin() {
		Join join = new Join(p("a", "b"), q("b", "c"));
		Filter onJoinVariable = new Filter(join.clone(), new Compare(Var.of("a"), Var.of("b"), Compare.CompareOp.EQ));
		Filter onOtherVariable = new Filter(join.clone(),
				new Compare(Var.of("a"), Var.of("c"), Compare.CompareOp.EQ));

		LeoOperatorKey first = LeoOperatorKey.from(onJoinVariable, "", LeoOperatorKey.ConstantMode.EXACT);
		LeoOperatorKey second = LeoOperatorKey.from(onOtherVariable, "", LeoOperatorKey.ConstantMode.EXACT);
		assertNotEquals(first, second,
				"FILTER(?a=?b) and FILTER(?a=?c) over the same join are different predicates; key="
						+ first.structuralFingerprint());
	}

	@Test
	void distinctOverDifferentProjectionsMustNotShareAStructuralFingerprint() {
		Join join = new Join(p("s", "o"), q("o", "z"));
		Distinct distinctSubject = new Distinct(new Projection(join.clone(), new ProjectionElemList(
				new ProjectionElem("s"))));
		Distinct distinctSubjectObject = new Distinct(new Projection(join.clone(), new ProjectionElemList(
				new ProjectionElem("s"), new ProjectionElem("o"))));

		LeoOperatorKey first = LeoOperatorKey.from(distinctSubject, "", LeoOperatorKey.ConstantMode.EXACT);
		LeoOperatorKey second = LeoOperatorKey.from(distinctSubjectObject, "", LeoOperatorKey.ConstantMode.EXACT);
		// LMDB persists operatorType + structuralFingerprint (+ empty displayBindings for unary operators).
		assertEquals(first.operatorType(), second.operatorType());
		assertNotEquals(first.structuralFingerprint(), second.structuralFingerprint(),
				"DISTINCT ?s and DISTINCT ?s ?o have different multipliers but share the LMDB learning key");
	}

	@Test
	void largeValuesTablesWithDifferentRowsMustNotCollide() {
		// "Aa" and "BB" have identical String.hashCode(); VALUES tables beyond 32 rows are keyed by 32-bit hashes.
		BindingSetAssignment first = values("Aa");
		BindingSetAssignment second = values("BB");
		LeoOperatorKey firstKey = LeoOperatorKey.from(first, "", LeoOperatorKey.ConstantMode.EXACT);
		LeoOperatorKey secondKey = LeoOperatorKey.from(second, "", LeoOperatorKey.ConstantMode.EXACT);
		assertNotEquals(firstKey, secondKey,
				"different VALUES contents must not share an EXACT learning key; key="
						+ firstKey.structuralFingerprint());
	}

	// ---------------------------------------------------------------- LeoConfidenceModel (candidate 7)

	@Test
	void nonFiniteSamplesMustNotCountAsPerfectEvidence() {
		LeoConfidenceModel learned = LeoConfidenceModel.empty().observe(10.0d, 1_000.0d, 10.0d, 1_000.0d, 1L);
		LeoConfidenceModel polluted = learned;
		for (int i = 0; i < 5; i++) {
			polluted = polluted.observe(Double.NaN, Double.NaN, Double.NaN, Double.NaN, 2L + i);
		}
		String state = "before: correction=" + learned.rowCorrectionRatio() + " confidence=" + learned.confidence()
				+ " samples=" + learned.sampleCount() + "; after 5 NaN samples: correction="
				+ polluted.rowCorrectionRatio() + " confidence=" + polluted.confidence() + " samples="
				+ polluted.sampleCount();
		assertEquals(learned.rowCorrectionRatio(), polluted.rowCorrectionRatio(), 1.0e-9d,
				"invalid samples must not erase a learned correction: " + state);
		assertTrue(polluted.confidence() <= learned.confidence(),
				"invalid samples must not raise confidence: " + state);
	}

	@Test
	void symmetricPlanFlipErrorsMustNotBiasTheCorrectionRatio() {
		// Plan flips alternate a 100x under-estimate and a 100x over-estimate: geometric mean error is 1.
		LeoConfidenceModel model = LeoConfidenceModel.empty();
		StringBuilder trace = new StringBuilder();
		for (int i = 0; i < 20; i++) {
			model = i % 2 == 0 ? model.observe(1.0d, 100.0d, 1.0d, 100.0d, i)
					: model.observe(100.0d, 1.0d, 100.0d, 1.0d, i);
			trace.append(String.format("%.3f ", model.rowCorrectionRatio()));
		}
		double ratio = model.rowCorrectionRatio();
		assertTrue(ratio >= 0.1d && ratio <= 10.0d,
				"linear-space EWMA must not drift to a large multiplier for log-symmetric errors; trace=" + trace);
	}

	@Test
	void oneEmptyExecutionMustNotCollapseTheCorrectionBelowOneRow() {
		LeoConfidenceModel model = LeoConfidenceModel.empty().observe(50.0d, 0.0d, 50.0d, 0.0d, 1L);
		double correctedRows = 50.0d * model.rowCorrectionRatio();
		assertTrue(correctedRows >= 1.0d,
				"a single zero-row execution should not correct a 50-row estimate to " + correctedRows
						+ " (ratio=" + model.rowCorrectionRatio() + ", confidence=" + model.confidence() + ")");
	}

	@Test
	void oneOutlierMustNotCapConfidenceForeverAfterManyAccurateSamples() {
		LeoConfidenceModel model = LeoConfidenceModel.empty().observe(1.0d, 100_000.0d, 1.0d, 100_000.0d, 1L);
		for (int i = 0; i < 50; i++) {
			model = model.observe(100.0d, 100.0d, 100.0d, 100.0d, 2L + i);
		}
		assertTrue(model.confidence() >= 0.5d,
				"after 50 accurate samples confidence is " + model.confidence() + " (rowQErrorMax="
						+ model.rowQErrorMax() + ", ratioMean=" + model.rowRatioMean() + ", correction="
						+ model.rowCorrectionRatio() + ")");
	}

	@Test
	void confidenceMustStillDecayWhenTheEpochCounterRegresses() {
		LeoConfidenceModel model = LeoConfidenceModel.empty();
		for (int i = 0; i < 10; i++) {
			model = model.observe(100.0d, 120.0d, 100.0d, 120.0d, 1_000_000L);
		}
		double decayed = model.decayedConfidence(10L, 4_096L);
		assertTrue(decayed < model.confidence(),
				"epoch regression (store rebuilt/sidecar mismatch) leaves confidence undecayed forever: "
						+ decayed);
	}

	// ---------------------------------------------------------------- LeoEvidence / rollout (candidate 8)

	@Test
	void zeroConfidenceSketchMustNotOutrankWellEvidencedFeedback() {
		LeoEvidence sketch = LeoEvidence.queryLocalVirtualSketch(1_000_000.0d, 1_000_000.0d, 0.0d, 0L, "sketch");
		LeoEvidence feedback = LeoEvidence.scalarCorrection(10.0d, 10.0d, 0.95d, 200L, "feedback");
		Optional<LeoEvidence> best = LeoEvidence.bestOf(List.of(sketch, feedback));
		assertEquals("feedback", best.orElseThrow().source(),
				"bestOf ranks by Kind before confidence: selected " + best.orElseThrow());
	}

	@Test
	void unrecognizedProfileNameMustFailClosed() {
		for (String typo : List.of("disabled", "false", "none", "of", "0")) {
			LeoRolloutProfile parsed = LeoRolloutProfile.parse(typo, LeoRolloutProfile.SAFE_CARDINALITY_CORRECTION);
			assertFalse(parsed.cardinalityCorrectionEnabled(),
					"profile value '" + typo + "' silently enables cardinality correction (" + parsed + ")");
		}
	}

	@Test
	void rolloutLadderMustBeMonotone() {
		LeoRolloutProfile[] ladder = LeoRolloutProfile.values();
		List<String> violations = new ArrayList<>();
		for (int i = 1; i < ladder.length; i++) {
			LeoRolloutProfile lower = ladder[i - 1];
			LeoRolloutProfile higher = ladder[i];
			if (lower.planLifecycleEnforced() && !higher.planLifecycleEnforced()) {
				violations.add(higher + " drops lifecycle enforcement enabled by lower rung " + lower);
			}
			if (signature(lower).equals(signature(higher))) {
				violations.add(lower + " == " + higher + " (" + signature(higher) + ")");
			}
		}
		assertTrue(violations.isEmpty(), "rollout ladder violations: " + violations);
	}

	// ---------------------------------------------------------------- helpers

	private static String signature(LeoRolloutProfile profile) {
		return profile.observationEnabled() + "/" + profile.cardinalityCorrectionEnabled() + "/"
				+ profile.planRerankingEnabled() + "/" + profile.planLifecycleEnforced();
	}

	private static BindingSetAssignment values(String collidingLabel) {
		List<BindingSet> rows = new ArrayList<>();
		MapBindingSet colliding = new MapBindingSet();
		colliding.addBinding("x", VF.createLiteral(collidingLabel));
		rows.add(colliding);
		for (int i = 0; i < 40; i++) {
			MapBindingSet row = new MapBindingSet();
			row.addBinding("x", VF.createLiteral("row-" + i));
			rows.add(row);
		}
		BindingSetAssignment assignment = new BindingSetAssignment();
		assignment.setBindingNames(java.util.Set.of("x"));
		assignment.setBindingSets(rows);
		return assignment;
	}

	private static TupleExpr leftDeep(TupleExpr... factors) {
		TupleExpr result = factors[0];
		for (int i = 1; i < factors.length; i++) {
			result = new Join(result, factors[i]);
		}
		return result;
	}

	private static StatementPattern p(String subject, String object) {
		return new StatementPattern(Var.of(subject), Var.of("_const_p", VF.createIRI("urn:p")), Var.of(object));
	}

	private static StatementPattern q(String subject, String object) {
		return new StatementPattern(Var.of(subject), Var.of("_const_q", VF.createIRI("urn:q")), Var.of(object));
	}
}
